\title{The Lattice of Witnesses to Rainbow Forest Obstructions}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
An edge-colored graph admits a \emph{total rainbow forest} of size $t$---a set of
$t$ edges that is simultaneously acyclic and rainbow (all colors distinct)---exactly
when two associated matroids, the graphic matroid $M_1$ and the color partition
matroid $M_2$, share a common independent set of size $t$. By matroid intersection
duality, no such common independent set exists precisely when some subset $A$ of the
edge set $E$ certifies a failure of the \emph{Rainbow Forest Inequality},
$r_1(A) + r_2(E \setminus A) < t$, where $r_i$ is the rank function of $M_i$. A
natural conjecture asserts that for a minimal obstruction this certifying subset is
unique. We investigate the claim abstractly at the level of matroid rank functions.
The uniqueness conjecture is \emph{false}: we exhibit a two-element ground set with
both matroids equal to the uniform matroid $U_{1,2}$ for which two distinct subsets
attain the minimum. In its place we establish the correct structural theorem: the
objective $g(A) = r_1(A) + r_2(E \setminus A)$ is submodular; its minimizers are
closed under intersection and union and hence form a lattice; and consequently there
exist a unique least and a unique greatest witnessing subset. We further show that
edge-deletion minimality cannot restore uniqueness, since the intersection number is
monotone under deletion. All results follow from the four matroid rank axioms alone.
\end{abstract}

\medskip
\noindent\textbf{Keywords.} rainbow forest, matroid intersection, submodularity,
rank function, lattice of minimizers, weak duality, uniform matroid.

\section{Introduction}

\subsection{Rainbow forests and obstructions}
Let $G = (V,E)$ be a graph whose edges are colored by $c : E \to \{1,\dots,k\}$. A
\emph{total rainbow forest} is a set $I \subseteq E$ that is both a forest (contains
no cycle) and rainbow ($c$ is injective on $I$). Total rainbow forests package two
independence demands: a structural demand (acyclicity, i.e.\ graphic independence)
and a diversity demand (distinct colors, i.e.\ one representative per color class).

Both demands are instances of matroid independence. The forests of $G$ are the
independent sets of the \emph{graphic matroid} $M_1$; the rainbow sets are the
independent sets of the \emph{partition matroid} $M_2$ whose blocks are the color
classes. A total rainbow forest is thus a \emph{common independent set} of $M_1$ and
$M_2$, and the maximum-size problem is precisely \emph{matroid intersection}. This
paper studies the dual side: the subsets that certify impossibility.

\subsection{The uniqueness conjecture}
The motivating conjecture claims that if $G$ is a minimal obstruction to total
rainbow forests of size $t$, then the certifying subset $A$ with
$r_1(A) + r_2(E \setminus A) < t$ is \emph{unique}. We show this is false and
identify the correct replacement: a lattice structure on the certifying subsets,
with canonical least and greatest members. Everything is carried out at the level of
abstract rank functions, so the results apply to any pair of matroids on a common
ground set.

\subsection{Contributions}
\begin{enumerate}[label=(\arabic*)]
  \item The Rainbow Forest Inequality (weak duality), Theorem~\ref{thm:rfi}.
  \item A single witness blocks all forests of a given size, Theorem~\ref{thm:block}.
  \item Submodularity of the objective, Theorem~\ref{thm:submod}.
  \item Minimizers closed under intersection and union, Theorems~\ref{thm:inf} and
        \ref{thm:sup}.
  \item Unique least and greatest witnesses, Theorems~\ref{thm:least} and
        \ref{thm:greatest}.
  \item Refutation of uniqueness, Theorems~\ref{thm:fail} and \ref{thm:notunique}.
  \item Minimality does not help, Proposition~\ref{prop:mono}.
\end{enumerate}

\section{Preliminaries: matroid rank functions}
We work with a finite ground type $\alpha$ with decidable equality; all sets are
finite subsets (finsets) of $\alpha$. A ground set is a distinguished finset $E$.

\begin{definition}[Matroid rank function]
A function $r : \Pfin(\alpha) \to \mathbb{N}$ is a \emph{matroid rank function} if:
\begin{itemize}
  \item[(R0)] Normalization: $r(\varnothing) = 0$.
  \item[(R1)] Monotonicity: $X \subseteq Y \implies r(X) \le r(Y)$.
  \item[(R2)] Unit increase: $r(X \cup \{e\}) \le r(X) + 1$ for every element $e$.
  \item[(R3)] Submodularity: $r(X\cup Y) + r(X\cap Y) \le r(X) + r(Y)$ for all
        $X,Y$.
\end{itemize}
Elements outside the intended ground set act as loops, so restricting to subsets of
a fixed $E$ loses nothing.
\end{definition}

\begin{lemma}[Rank bounded by cardinality]\label{lem:card}
For every finset $X$, $r(X) \le |X|$.
\end{lemma}
\begin{proof}
Induct on $X$. The empty case is (R0). If $x \notin X$, then (R2) gives
$r(X\cup\{x\}) \le r(X) + 1 \le |X| + 1 = |X\cup\{x\}|$.
\end{proof}

\begin{definition}[Independence]
A finset $I$ is \emph{independent} for $r$ if $r(I) = |I|$.
\end{definition}

\begin{lemma}[Hereditary property]\label{lem:hered}
If $I$ is independent and $J \subseteq I$, then $J$ is independent.
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:card}, $r(J) \le |J|$. Conversely, adjoining the elements of
$I\setminus J$ one at a time and applying (R2) yields
$r(I) \le r(J) + |I\setminus J|$. Since $I$ is independent,
$|I| = r(I) \le r(J) + |I\setminus J|$ and $|I| = |J| + |I\setminus J|$, so
$|J| \le r(J)$. Hence $r(J) = |J|$.
\end{proof}

\section{The Rainbow Forest Inequality}
Fix a ground set $E$ and two matroid rank functions $r_1, r_2$.

\begin{definition}
For $A \subseteq E$, define $g(A) = r_1(A) + r_2(E \setminus A)$.
\end{definition}

\begin{theorem}[Rainbow Forest Inequality; weak duality]\label{thm:rfi}
Let $I \subseteq E$ be a common independent set (independent for both $r_1$ and
$r_2$). Then for every subset $A$,
\[
  |I| \le g(A) = r_1(A) + r_2(E\setminus A).
\]
\end{theorem}
\begin{proof}
Partition $I$ by $A$: $I = (I\cap A) \sqcup (I\setminus A)$, so
$|I| = |I\cap A| + |I\setminus A|$. Since $I\cap A \subseteq I$ and $I$ is
$r_1$-independent, Lemma~\ref{lem:hered} gives $r_1(I\cap A) = |I\cap A|$; by (R1),
$|I\cap A| \le r_1(A)$. Since $I\setminus A \subseteq I$ and $I$ is
$r_2$-independent, $r_2(I\setminus A) = |I\setminus A|$; and
$I\setminus A \subseteq E\setminus A$, so by (R1),
$|I\setminus A| \le r_2(E\setminus A)$. Adding gives $|I| \le g(A)$.
\end{proof}

\begin{theorem}[A single witness blocks all forests]\label{thm:block}
If some subset $A$ satisfies $g(A) < t$, then there is no common independent set
$I \subseteq E$ with $|I| \ge t$.
\end{theorem}
\begin{proof}
Otherwise $t \le |I| \le g(A) < t$ by Theorem~\ref{thm:rfi}, a contradiction.
\end{proof}

We call any $A$ with $g(A) < t$ a \emph{witness} to the obstruction at level $t$.

\section{Submodularity and the lattice of witnesses}

\begin{theorem}[Submodularity of $g$]\label{thm:submod}
For all $A, B \subseteq E$, $\;g(A\cup B) + g(A\cap B) \le g(A) + g(B)$.
\end{theorem}
\begin{proof}
Apply (R3) to $r_1$ on $(A,B)$ and to $r_2$ on $(E\setminus A, E\setminus B)$. By De
Morgan on the ground set, $(E\setminus A)\cap(E\setminus B) = E\setminus(A\cup B)$
and $(E\setminus A)\cup(E\setminus B) = E\setminus(A\cap B)$. Adding the two
inequalities and regrouping gives the claim.
\end{proof}

\begin{definition}[Minimizer]
$A \subseteq E$ is a \emph{minimizer} of $g$ if $g(A) \le g(B)$ for all
$B \subseteq E$. Let $m = \min_{B\subseteq E} g(B)$; the minimizers are the subsets
with $g(A) = m$.
\end{definition}

A minimizer exists because $\mathcal{P}(E)$ is finite and nonempty.

\begin{theorem}[Closure under intersection]\label{thm:inf}
If $A$ and $B$ are minimizers, so is $A\cap B$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:submod}, $g(A\cup B) + g(A\cap B) \le g(A) + g(B) = 2m$. Both
terms on the left are $\ge m$ by minimality, forcing both to equal $m$; in
particular $g(A\cap B) = m$.
\end{proof}

\begin{theorem}[Closure under union]\label{thm:sup}
If $A$ and $B$ are minimizers, so is $A\cup B$.
\end{theorem}
\begin{proof}
The same inequality forces $g(A\cup B) = m$.
\end{proof}

Thus the family $\mathcal{M} = \{A : g(A) = m\}$ is a sublattice of
$(\mathcal{P}(E), \cap, \cup)$.

\begin{theorem}[Unique least witness]\label{thm:least}
There is a unique minimizer $A_{\min}$ contained in every minimizer.
\end{theorem}
\begin{proof}
Pick a minimizer $A_0$ of minimum cardinality. For any minimizer $A$,
Theorem~\ref{thm:inf} makes $A_0\cap A$ a minimizer with
$|A_0\cap A| \le |A_0|$; minimality forces $A_0\cap A = A_0$, i.e.\
$A_0 \subseteq A$. Uniqueness is immediate.
\end{proof}

\begin{theorem}[Unique greatest witness]\label{thm:greatest}
There is a unique minimizer $A_{\max}$ containing every minimizer.
\end{theorem}
\begin{proof}
Dually, pick a minimizer $A_0$ of maximum cardinality. For any minimizer $A$,
Theorem~\ref{thm:sup} makes $A\cup A_0$ a minimizer with $|A\cup A_0| \ge |A_0|$;
maximality forces $A \subseteq A_0$.
\end{proof}

Theorems~\ref{thm:least} and \ref{thm:greatest} are the corrected form of the
conjecture: not a unique witness, but a lattice with canonical smallest and largest
members.

\section{Refutation of the uniqueness conjecture}

Recall the uniform matroid $U_{1,2}$: on a two-element ground set a set is
independent iff it has at most one element. Its rank is the indicator of
non-emptiness.

\begin{definition}[Indicator rank]
Define $\rho(A) = 0$ if $A = \varnothing$ and $\rho(A) = 1$ otherwise.
\end{definition}

\begin{lemma}\label{lem:rho}
$\rho$ is a matroid rank function.
\end{lemma}
\begin{proof}
(R0) is immediate; (R1) and (R2) hold since $\rho \in \{0,1\}$ and $\rho$ is
monotone; (R3) holds by checking the finitely many emptiness cases.
\end{proof}

\begin{theorem}[Uniqueness fails]\label{thm:fail}
There exist $E$, matroid rank functions $r_1, r_2$, a target $t$, and distinct
subsets $A \ne B$ with $A, B \subseteq E$, $g(A) < t$ and $g(B) < t$.
\end{theorem}
\begin{proof}
Take $E = \{0,1\}$, $r_1 = r_2 = \rho$, $t = 2$. Then $g(\varnothing) = 0+1 = 1$,
$g(\{0\}) = g(\{1\}) = 1+1 = 2$, $g(\{0,1\}) = 1+0 = 1$. Both $\varnothing$ and
$\{0,1\}$ give $g = 1 < 2$.
\end{proof}

\begin{theorem}[Minimizer non-uniqueness]\label{thm:notunique}
In the same instance, $\varnothing$ and $\{0,1\}$ are both minimizers of $g$, so
uniqueness fails even at the exact minimum value $m = 1$.
\end{theorem}
\begin{proof}
From the table, $\min_A g(A) = 1$, attained exactly at $\varnothing$ and $\{0,1\}$.
\end{proof}

Here $A_{\min} = \varnothing$ and $A_{\max} = \{0,1\}$, and the minimizer lattice is
the two-element chain $\{\varnothing, \{0,1\}\}$. The conjecture failed by mistaking
a two-element lattice for a one-element one.

\section{Discussion: minimality cannot restore uniqueness}

\begin{proposition}[Monotonicity under deletion]\label{prop:mono}
The intersection number $\nu(E) = \min_{A\subseteq E} g(A) = \max\{|I| : I
\text{ common independent}, I\subseteq E\}$ cannot increase when an edge is deleted.
\end{proposition}
\begin{proof}[Sketch]
A common independent set of $E\setminus\{e\}$ is also one of $E$, so the max over
the larger set is at least the max over the smaller.
\end{proof}

Consequently, if $\nu(E) < t$ then every subgraph $E' \subseteq E$ has
$\nu(E') < t$, so obstructions are downward closed and the only edge-minimal
obstruction is $\varnothing$. Edge-minimality thus deletes the entire structure
rather than pinning down a unique witness. The robust invariant is the lattice of
witnesses.

\section{Algorithms}
\begin{itemize}
  \item \textbf{Certificate check.} Given $A$, return ``obstruction certified'' iff
        $r_1(A) + r_2(E\setminus A) < t$ (two rank evaluations; correct by
        Theorem~\ref{thm:block}).
  \item \textbf{Brute-force minimizer enumeration.} Evaluate $g$ over all
        $A \subseteq E$, record $m$ and $\mathcal{M}$; then $A_{\min} = \bigcap
        \mathcal{M}$, $A_{\max} = \bigcup \mathcal{M}$ (correct by
        Theorems~\ref{thm:inf}--\ref{thm:greatest}; cost $O(2^{|E|})$).
  \item \textbf{Submodular minimization.} Since $g$ is submodular, $A_{\min}$ and
        $A_{\max}$ can be found in polynomial time with a rank oracle.
\end{itemize}

\section{Applications}
Network design with diversity (distinct bands, vendors, routes), scheduling with
one-per-class resource limits, and pedagogy (a minimal example that submodular
minima need not be unique while the extreme minimizers always are).

\section{Future directions}
\begin{itemize}
  \item \textbf{Alternative minimality.} Is there a color-deletion or contraction
        notion under which $A_{\min} = A_{\max}$? Characterize matroid pairs for
        which the extremes coincide.
  \item \textbf{Strong duality.} Formalize $\max_I |I| = \min_A g(A)$ to upgrade
        Theorem~\ref{thm:block} to an equivalence.
  \item \textbf{Counting witnesses.} Relate the number of minimizers to the tight
        sets (a Dilworth-type count) of the distributive witness lattice.
  \item \textbf{Weighted version.} Extend $g$ and the lattice results to weighted
        matroid intersection.
\end{itemize}

\section{Conclusion}
From the four rank axioms we established weak duality, single-witness blocking, and
submodularity of $g$, forcing the minimizers into a lattice with unique least and
greatest members---the correct form of the uniqueness conjecture. The literal
conjecture is false, as a two-element uniform-matroid instance shows, and
edge-minimality cannot repair it. The lasting object is a lattice of cuts, bracketed
by its smallest and largest members.

