from itertools import chain, combinations
from typing import Callable, FrozenSet, List, Tuple

RankFn = Callable[[FrozenSet[int]], int]

def powerset(ground: FrozenSet[int]) -> List[FrozenSet[int]]:
    e = sorted(ground)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(e, k) for k in range(len(e) + 1))]

def g(E: FrozenSet[int], r1: RankFn, r2: RankFn, A: FrozenSet[int]) -> int:
    return r1(A) + r2(E - A)

def indicator_rank(A: FrozenSet[int]) -> int:
    return 0 if len(A) == 0 else 1

def minimizers(E: FrozenSet[int], r1: RankFn, r2: RankFn) -> Tuple[int, List[FrozenSet[int]]]:
    vals = {A: g(E, r1, r2, A) for A in powerset(E)}
    m = min(vals.values())
    return m, [A for A in vals if vals[A] == m]

# Both matroids = U_{1,2} on {0,1}; target t = 2.
E = frozenset({0, 1})
m, mins = minimizers(E, indicator_rank, indicator_rank)
print("minimum value m =", m)
print("minimizing subsets:", [sorted(A) for A in mins])
assert len(mins) == 2, "uniqueness should FAIL: two distinct witnesses"
print("Uniqueness conjecture refuted: two distinct minimizers exist.")

from itertools import chain, combinations
from typing import Callable, FrozenSet, List

RankFn = Callable[[FrozenSet[int]], int]

def powerset(g: FrozenSet[int]) -> List[FrozenSet[int]]:
    e = sorted(g)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(e, k) for k in range(len(e) + 1))]

def uniform_rank(k: int) -> RankFn:
    return lambda A: min(len(A), k)

def partition_rank(blocks):
    return lambda A: sum(1 for b in blocks if len(A & b) >= 1)

def g_obj(E, r1, r2, A):
    return r1(A) + r2(E - A)

def common_independent(E, r1, r2):
    return [I for I in powerset(E) if r1(I) == len(I) and r2(I) == len(I)]

# Check |I| <= g(A) for all common independent I and all A, and that
# the max size equals min_A g(A) (strong duality) on this instance.
E = frozenset({0, 1, 2})
r1 = uniform_rank(3)
r2 = partition_rank([frozenset({0, 1}), frozenset({2})])
cis = common_independent(E, r1, r2)
subs = powerset(E)
assert all(len(I) <= g_obj(E, r1, r2, A) for I in cis for A in subs)
max_size = max(len(I) for I in cis)
min_g = min(g_obj(E, r1, r2, A) for A in subs)
print("max total rainbow forest size:", max_size)
print("min_A g(A):", min_g)
print("weak duality holds; here max == min:", max_size == min_g)

