function CertifyObstruction(E, r1, r2, t, A):
    value <- r1(A) + r2(E \ A)
    return value < t

function LeastGreatestWitness(E, r1, r2):
    for each A subseteq E:
        val[A] <- r1(A) + r2(E \ A)
    m <- min over A of val[A]
    M <- { A : val[A] = m }
    A_min <- intersection of all A in M
    A_max <- union of all A in M
    return (m, A_min, A_max)

function IsMatroidRank(E, r):
    if r(empty) != 0: return false
    for each X subseteq E:
        for each element e in E:
            if r(X + e) > r(X) + 1: return false
        for each Y subseteq E:
            if X subseteq Y and r(X) > r(Y): return false
            if r(X union Y) + r(X inter Y) > r(X) + r(Y): return false
    return true

