from itertools import chain, combinations
from typing import Callable, FrozenSet, List

RankFn = Callable[[FrozenSet[int]], int]

def powerset(ground: FrozenSet[int]) -> List[FrozenSet[int]]:
    e = sorted(ground)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(e, k) for k in range(len(e) + 1))]

def is_matroid_rank(E: FrozenSet[int], r: RankFn) -> bool:
    """Verify the four rank axioms (R0)-(R3) for r on subsets of E:
    normalization, monotonicity, unit increase, and submodularity."""
    subs = powerset(E)
    if r(frozenset()) != 0:
        return False
    for X in subs:
        for e in E:
            if r(X | {e}) > r(X) + 1:          # (R2) unit increase
                return False
        for Y in subs:
            if X <= Y and r(X) > r(Y):          # (R1) monotonicity
                return False
            if r(X | Y) + r(X & Y) > r(X) + r(Y):  # (R3) submodularity
                return False
    return True

