import matplotlib.pyplot as plt
from itertools import chain, combinations

def powerset(g):
    e = sorted(g)
    return [frozenset(c) for c in chain.from_iterable(
        combinations(e, k) for k in range(len(e) + 1))]

def uniform_rank(k):
    return lambda A: min(len(A), k)

# Draw the Boolean lattice on {0,1,2}, highlighting the minimizers of g.
E = frozenset({0, 1, 2})
r1 = uniform_rank(1); r2 = uniform_rank(1)
subs = powerset(E)
vals = {A: r1(A) + r2(E - A) for A in subs}
m = min(vals.values())

# position nodes by cardinality (rank) and index within a rank
levels = {}
for A in subs:
    levels.setdefault(len(A), []).append(A)
pos = {}
for lvl, nodes in levels.items():
    for i, A in enumerate(sorted(nodes, key=lambda s: sorted(s))):
        pos[A] = (i - (len(nodes) - 1) / 2, lvl)

plt.figure(figsize=(7, 5))
for A in subs:
    for B in subs:
        if A < B and len(B) == len(A) + 1:
            x = [pos[A][0], pos[B][0]]; y = [pos[A][1], pos[B][1]]
            plt.plot(x, y, color="lightgray", zorder=1)
for A in subs:
    is_min = vals[A] == m
    plt.scatter(*pos[A], s=700, zorder=2,
                color="crimson" if is_min else "steelblue")
    lab = "{}" if not A else "".join(map(str, sorted(A)))
    plt.text(*pos[A], lab, ha="center", va="center", color="white", zorder=3)
plt.title("Boolean lattice on {0,1,2}: g-minimizers in red")
plt.axis("off")
plt.tight_layout()
plt.savefig("witness_lattice.png", dpi=150)
print("saved witness_lattice.png")
